#include <bits/stdc++.h>
int main(int c, char** v) { std::mt19937 r(atoi(v[1])); int n = r() % 7 + 2; std::set<std::pair<int,int>> e; int m = r() % (n * (n - 1)) + 1; for (int i = 0; i < 200 && (int)e.size() < m; i++) { int a = r() % n + 1, b = r() % n + 1; if (a != b) e.insert({a, b}); } std::vector<std::vector<int>> g(n + 1); for (auto [a, b] : e) g[a].push_back(b); int t = r() % n + 1; std::vector<int> d(n + 1, -1); std::vector<std::vector<int>> rg(n + 1); for (auto [a, b] : e) rg[b].push_back(a); std::queue<int> q; q.push(t); d[t] = 0; while (!q.empty()) { int x = q.front(); q.pop(); for (int u : rg[x]) if (d[u] == -1) { d[u] = d[x] + 1; q.push(u); } } std::vector<int> can; for (int x = 1; x <= n; x++) if (d[x] > 0) can.push_back(x); if (can.empty()) { e.insert({t == 1 ? 2 : 1, t}); g[t == 1 ? 2 : 1].push_back(t); can.push_back(t == 1 ? 2 : 1); d.assign(n + 1, -1); d[t] = 0; d[can[0]] = 1; } int s = can[r() % can.size()]; std::vector<int> path = {s}; std::set<int> used = {s}; int cur = s; while (cur != t) { std::vector<int> opts; for (int u : g[cur]) if (!used.count(u) && d[u] != -1) opts.push_back(u); if (opts.empty()) break; int nx = opts[r() % opts.size()]; if (r() % 2) for (int u : g[cur]) if (!used.count(u) && d[u] == d[cur] - 1) nx = u; path.push_back(nx); used.insert(nx); cur = nx; } if (cur != t) { path = {s}; cur = s; while (cur != t) { for (int u : g[cur]) if (d[u] == d[cur] - 1) { cur = u; break; } path.push_back(cur); } } printf("%d %d\n", n, (int)e.size()); for (auto [a, b] : e) printf("%d %d\n", a, b); printf("%d\n", (int)path.size()); for (int x : path) printf("%d ", x); puts(""); }
